enum ChronoUnit {
    MINUTES, HOURS
}

public static void main(String[] args) {
    int ms = 0;
    float time = 1.5f;
    ChronoUnit unit = ChronoUnit.MINUTES;
    switch (unit) {
        case MINUTES:
            int seconds = (int) (time * 60);
            ms = seconds * 1000;
            break;

        case HOURS:
            int minutes = (int) (time * 60);
            int seconds = minutes * 60;
            ms = seconds * 1000;
            break;
    }
    out.println(ms);
}

